COURSE = dict(id="mf-start", level="foundation", title="Mutual funds, from zero", sec="mf", track="mf-basics", topic="Mutual funds", tag="MF",
  blurb="What a mutual fund is, the kinds you can choose from, what risk and cost really mean, and how to start safely. No jargon you have not been taught first.",
  hook="You do not need to pick shares or time the market to invest. A mutual fund lets many people pool money and have a professional manage it. Learn the few ideas that matter, and the rest becomes easy.",
  fun=["Each unit of a fund is a tiny slice of everything the fund owns, so a small amount can still be spread across many companies.", "The same fund can be bought in a Direct plan or a Regular plan, and the cost difference compounds over the years."],
  traps=["Judging a fund only by last year's return.", "Buying a fund without checking its riskometer against your own comfort.", "Ignoring cost because the difference looks small each year."],
  lessons=[
  dict(title="What a mutual fund is", intro="A mutual fund collects money from many people and invests it together, so each person owns a small share of a larger, spread-out portfolio.", concepts=[
    ("Mutual fund", "A mutual fund is a pool of money collected from many investors and invested by a professional in shares, bonds or other assets.", "Five hundred colleagues each put in ₹5,000, and one manager invests the combined ₹25 lakh on their behalf."),
    ("Unit", "A unit is your share of the fund. You buy it with your money, and how many you own shows how much of the pool is yours.", "Putting in ₹10,000 when one share of the pool costs ₹20 gives you 500 slices of the pool."),
    ("NAV", "NAV is the price of one unit. It is the fund's total value, after costs, divided by the number of units, and it is worked out every business day.", "A pool worth ₹200 crore with 10 crore units is priced at ₹20 per unit at the end of the day."),
    ("Fund house", "A fund house, or AMC, is the company that runs the fund, employs the manager and handles the paperwork, under rules set by SEBI.", "A company with licensed managers and analysts runs dozens of funds and reports to the market regulator."),
    ("SEBI", "SEBI is the market regulator. It sets rules on how funds invest, what they disclose and how they treat investors, and the fund's assets are kept separate from the fund house's own money.", "If the company that runs a fund ran into trouble, the money in the pool would still belong to the unit holders.")],
    client=("“Is a mutual fund a company that keeps my money?”", "A friend who thinks the fund house owns the savings."), talk="“No. Your money buys units of a pool, and the pool's assets are kept separate and overseen by a trustee under SEBI rules. The fund house manages the pool but does not own it.”", remember=["A fund pools many people's money.", "You own units, and the unit price moves daily.", "SEBI sets the rules and the assets are kept separate."]),
  dict(title="The kinds of funds", intro="Funds differ by what they hold. That decides how much they can grow and how much they can fall.", concepts=[
    ("Equity fund", "An equity fund invests mainly in company shares. It has the highest growth potential and the biggest ups and downs, so it suits goals at least five years away.", "A fund holding shares of many large companies can rise sharply in a good year and fall in a bad one."),
    ("Debt fund", "A debt fund lends money by buying bonds and similar instruments. It is usually steadier than an equity fund but is not without risk.", "A fund that mostly holds government and company bonds earns interest and moves less than a shares fund."),
    ("Hybrid fund", "A hybrid fund mixes shares and bonds in one fund, so the manager balances growth and stability for you.", "A fund keeping about two thirds in shares and the rest in bonds falls less in a bad year than an all-shares fund."),
    ("Index fund", "An index fund simply copies a market index such as the Nifty 50, holding the same companies in the same proportion. It has no manager picking stocks and usually charges less.", "A fund that holds the fifty biggest companies in fixed weights moves almost exactly like that list of companies."),
    ("ELSS", "An ELSS is an equity fund with a three-year lock-in, and under the old tax regime up to ₹1.5 lakh a year invested qualifies for a deduction.", "A salaried person puts money in a share-based fund that cannot be withdrawn for three years and claims a tax deduction.")],
    client=("“Which type is best?”", "A first-time investor who wants one answer."), talk="“There is no single best. It depends on the goal and how long you have. Money needed within a few years suits steadier funds, and money for ten years or more can handle shares.”", remember=["Equity grows more but swings more.", "Debt is steadier but not without risk.", "Match the fund to the goal and the time you have."]),
  dict(title="Risk, return and time", intro="Higher possible growth always comes with a bigger chance of loss. Time and spreading money around are how investors manage that.", concepts=[
    ("Risk", "Risk is the chance that your investment ends up worth less than you hoped, or less than you put in, at the time you need it.", "A person needing money in one year finds the fund down 10% just when the bills arrive."),
    ("Riskometer", "The riskometer is the label every fund must show, from Low to Very High, telling you how risky the fund's holdings are.", "A fund holding mostly small company shares carries the top label, while one holding short bonds carries a low one."),
    ("Time horizon", "Time horizon is how long you can leave the money invested before you need it. The longer it is, the more time prices have to recover from falls.", "Money for a house in two years and money for retirement in twenty years should not sit in the same kind of fund."),
    ("Diversification", "Diversification means spreading money across many holdings so that one bad company or sector cannot hurt you badly.", "Owning slices of hundreds of businesses means one company's failure barely moves your total."),
    ("Volatility", "Volatility is how much a price swings up and down. It is the bumpy ride, and it is normal for equity funds even when they do well over the long run.", "A fund that gains 30% one year and loses 12% the next is bumpy, even if the ten-year result is good.")],
    client=("“My fund fell 8% this month. Should I sell?”", "A new investor shaken by a fall."), talk="“Falls are part of equity investing. If your goal is still years away and nothing about your plan has changed, selling locks in the loss. If the money is needed soon, it should not have been in equity.”", remember=["Higher growth comes with bigger swings.", "Check the riskometer against your comfort.", "Time and diversification reduce the damage of falls."]),
  dict(title="What a fund costs you", intro="Every fund charges a small yearly fee. The amount looks tiny, but over twenty years it can change your final sum by lakhs.", concepts=[
    ("Expense ratio", "The expense ratio is the yearly fee, shown as a percentage of your money, that pays for running the fund. It is taken from the fund's value, so you never see a bill.", "A fund that charges 1.5% a year keeps ₹1,500 from every ₹1 lakh each year before you see any return."),
    ("Direct plan", "A Direct plan is bought straight from the fund house, with no distributor in between, so it has a lower expense ratio than the Regular plan of the same fund.", "Buying through the fund house's own website gives the same portfolio at a smaller yearly charge."),
    ("Regular plan", "A Regular plan is bought through a distributor or adviser, whose service is paid out of a higher expense ratio.", "Buying through an agent who helps you choose and review costs a bit more each year inside the fund."),
    ("Exit load", "An exit load is a fee charged if you sell units within a set period, often a year, to discourage quick selling.", "Selling after eight months attracts a 1% charge, while selling after thirteen months does not."),
    ("Growth option", "In a Growth option, profits stay in the fund and increase the unit price, instead of being paid out, so they keep compounding.", "Choosing this means no payouts arrive and the unit price simply rises over time as gains build.")],
    client=("“Why should I care about 1% a year?”", "A friend who finds the fee too small to matter."), talk="“Over twenty years, a 1% yearly difference can take lakhs off the final amount because the fee is charged on a growing balance. Check the cost before you buy.”", remember=["Costs are taken inside the fund, every year.", "Direct plans cost less than Regular plans.", "Check the exit load before you invest."]),
  dict(title="How to start safely", intro="Starting takes a few steps: a one-time KYC, a choice of fund, a way to pay, and a habit you can keep.", concepts=[
    ("KYC", "KYC is a one-time identity check with your PAN and address proof that you must complete before investing in any fund.", "A new investor completes an online identity check using a PAN and Aadhaar-linked verification before buying her first fund."),
    ("Folio", "A folio is your account number with a fund house. It records every unit you hold and every purchase and sale.", "All of one investor's units with a fund house are tracked under a single number."),
    ("SIP", "An SIP, or systematic investment plan, moves a fixed amount from your bank into a fund on a set date every month, which makes investing a habit.", "₹5,000 leaves the account on the 5th of every month and buys units automatically."),
    ("Lump sum", "A lump sum is putting in a larger amount all at once, instead of in monthly instalments.", "A bonus of ₹2 lakh is invested in one go on a single day."),
    ("Nominee", "A nominee is the person you name to receive your units if you die, which saves your family time and paperwork.", "A father names his daughter, so she can claim his investments without a long legal process.")],
    client=("“I get a bonus once a year and a salary every month. How should I invest?”", "A working professional with both kinds of money."), talk="“Use a monthly SIP for your salary so it becomes a habit. For the bonus, decide the goal first, then invest it in a fund that suits that goal's time frame. Always add a nominee.”", remember=["Complete KYC once, then you can invest in any fund.", "An SIP turns investing into a monthly habit.", "Add a nominee so your family can claim."])
  ])
